-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExcd1926532b15$doc_the_public_procurement_act_2063_2007__2063_public_procurement_act_2063_pdf$CODExcd1926532b15$,$CODEx7c20beffb92d$The Public Procurement Act, 2063 (2007)$CODEx7c20beffb92d$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2063,2007,60,$CODExe9430b96f806$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "1\nThe Public Procurement Act, 2063 (2007) \nDate of certification and publication  \n30 paush 2063 (14 January 2007)  \nAct number 36 of the year 2007  \nAn Act Made to Provide for Public Procurement  \nPreamble : Whereas, it is expedient to make legal provisions in order to make the \nprocedures, processes and decisions relating to pub lic procurement much more open, \ntransparent, objective and reliable,   \nobtain the maximum returns of public expenditures i n an economical and rational \nmanner by promoting competition, fairness, honesty,  accountability and reliability in \npublic procurement processes, and;   \nensure good governance by enhancing the managerial capacity of procurement of  \npublic entities in procuring, or causing to be proc ured, construction work  and \nprocuring goods, consultancy services and other ser vices by such entities  and by \nensuring the equal opportunity for producers, selle rs, suppliers, construction \nentrepreneurs or service providers to participate i n public procurement processes \nwithout any discrimination;   \nNow, therefore, the House of Representatives has en acted this Act in the First Year of \nthe issuance of the Proclamation of the House of Representatives, 2007.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "CHAPTER- 1", "title": "CHAPTER- 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title and Commencement : (1) This Act may be called “Public", "content": "Procurement Act, 2007.\"   \n(2) It shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions : Unless the subject or context otherwise requires, in this Act,-", "content": "2\n(a)  “Procurement” means acquisition of any goods, consultancy services or \nother services or carrying out or causing to be car ried out any \nconstruction works, by a public entity pursuant to this Act;  \n(b)  “Public Entity” means the following entity:-  \n(1) Constitutional organ or body, Court, Ministry, Secretariat, \nCommission, Department of the Government of Nepal o r any other \nGovernmental Entity or Office thereunder,  \n(2)  Corporation, Company, Bank or Board owned or c ontrolled fully or \nin majority by the Government of Nepal or Commissio n, Institute, \nAuthority, Corporation, Academy, Board, Center, Cou ncil \nestablished at the public level or formed by the Go vernment of \nNepal under the laws in force and other corporate b ody of a similar \nnature,  \n(3)  University, College, Research Center, which is  operated by the \nGovernment of Nepal or receives grants fully or in majority from \nthe Government of Nepal, and other Academic or Educ ational \nInstitution of a similar nature,  \n(4)  Local body,  \n(5)  Development Board formed under the Dev elopment  Board Act, \n1956,  \n (6)  Body operated with loan or grant of the Gover nment of Nepal, and  \n(7)  Other Bodies as specified by the Government of  Nepal by \npublishing a notification in the Nepal Gazette, as a Public Entity;  \n(c)   “Goods” means any kind of object, whether mov able or immovable, and \n this term includes services incidental to the supp ly of such goods;  \n(d)  “Construction Work” means work such as site pr eparation, excavation, \n 3\nerection, building, installation of equipment or go ods and decoration etc, \nassociated with the construction, reconstruction, d emolition, repair or \nrenovation of any structure or works, and this term  also includes services \nincidental to construction work such as mapping, la boratory testing, \nsatellite photography and seismic investigation;  \n(e)   “Consultancy Service” means any study, resear ch, survey, design, \n drawing, supervision, training, testing, software development service or \n other intellectual or professional service of a si milar nature;  \n(f)   “Other Services” means the act of hiring moto r vehicles, equipment or \n goods, carriage or repair and maintenance of goods ;   \n(g)  “Bid” means a document setting out price, prop osal or rate submitted by \na bidder in the format specified by a Public Entity  as per the notice \npublished by that entity for procurement;  \n(h)   “Bidder” means any person, firm, organization  or company that submits \n or may submit bid to take part in procurement proc eedings;  \n(i)  “Bidding Document” means a document prepared b y the concerned \nPublic Entity making invitation to bid for submissi on by bidders by \nfilling up or preparing price or proposal or rate i n such document and \nthis term also includes instructions to bidders, sp ecifications, drawing, \ndesign, terms of reference, schedule of work, evalu ation criteria, bill of \nquantities, conditions of contract and similar other documents;  \n(j)  “Procurement Contract” means a procurement con tract entered into \nbetween a Public Entity and a supplier or construct ion entrepreneur or \nconsultant or service provider pursuant to Section 52;  \n(k)  “Public Procurement Monitoring Office” means t he Public Procurement \nMonitoring Office established under Section 64;  \n(l)   \"Competent Authority\" means an authority auth orized under this Act or \n 4\n the rules made thereunder to approve proceedings r egarding \n procurement;   \n(m)  “Security” means retention money or earnest mo ney furnished as \nsecurity pending the completion of any obligation/w ork, and this term \nalso includes bid security or performance security or an amount \nfurnished for security required to be so furnished for any other reason;  \n(n)  “Special Circumstance” means a circumstance re sulted from natural or \ndivine calamity and sudden or unexpected special ci rcumstance such as \ndrought, no rainfall, deluge, earthquake, flood, la ndslide and firing, and \nthis term also includes a circumstance such as war or internal conflict;  \n(o)  “Local Body” means Village Development Committ ee, Municipality or \nDistrict Development Committee constituted under th e Local Self-\ngovernance Act, 1998;  \n(p)   “Joint Venture” means the act of carrying out  any work jointly by two or \n more companies or firms with joint or several liab ilities;  \n(q)   “Agent” means any person, firm or company who  takes agency of any \n national or foreign person, firm or company;  \n(r)  “One Level Higher Authority” means in relation  to governmental \nentities, in the case of the head of office, the he ad of a regional office \nwhere there is such regional office and the departm ental head of the \nconcerned department where there is no regional off ice, in the case of \nregional head, the departmental head of the concern ed department, in the \ncase of departmental head, the secretary to the con cerned ministry, \nsecretariat or commission, in the case of a Secreta ry, the concerned \ndepartmental Minister or Minister of state, and in the case of a Secretary \nor administrative head of a constitutional organ or  body, the head of the \nconcerned constitutional organ or body and in the c ase of other public \n 5\nentities, the head of an entity that is one level h igher than the procuring \nentity and the board of directors or similar other body of such Public \nEntity where there is no such entity;   \n(s)  “Donor Party\" means any foreign country or int ernational or foreign \norganization, which provides foreign assistance in the form of loan or \ngrant to the Government of Nepal under a bilateral or multilateral \nagreement;  \n (t)  “Ration” means the goods in-kind specified by  the Government of Nepal \nin respect of food for the Nepal Army, Nepal Police, Armed Police Force \nand governmental employees specified by the Governm ent of Nepal; \npatients at hospitals, detainees in prisons, animals and birds etc;  \n(u)  “Prescribed” or “as prescribed” means prescrib ed or as prescribed in the \nrules framed under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Procurement to be made as per this Act : (1) In making procurement, a Public", "content": "Entity shall have to make such procurement by compl ying with the procedures \nset out in this Act.  \n(2) Any procurement made in such a manner as to be contrary to Sub-\nsection (1) shall be void and invalid.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "4", "title": "Description of Goods, Construction Works and Se rvices to be Prepared :", "content": "(1) Prior to procuring goods, construction works or  services, a Public Entity \nshall have to prepare a specifications, plan, drawi ng, design, special \nrequirement or other descriptions pertaining thereto.  \n 6\n(2) The description as referred to in Sub-section ( 1) shall be prepared \non the basis of relevant objective technical and qu ality characteristics and \nfunctions of such goods, construction works or services.  \n(3) In preparing the description pursuant to sub-Se ctions (1) and (2), \nunless there exists any other way of mentioning clearly in an intelligible manner \nthe characteristics of the goods, construction work s or services, a particular \nbrand, trademark, name, patent, design, type, origi n or producer’s name cannot \nbe mentioned .  \nProvided that where there is no other way than such  mentioning, a \nparticular brand, trademark, name, patent, design, type, origin or producer’s \nname shall be mentioned and  the words “equivalent to” shall be mentioned \nthereafter.  \n(4) In mentioning in the bidding documents or prequ alification \ndocuments, the description of the technical or qual ity characteristics of the \ngoods or construction works or other services, and requirements or symbols or \nterminologies relating to testing, marking, packagi ng, labeling or conformity \ncertificate, no description, requirements, symbols or terminologies can be so \nmentioned as to be irrelevant to the function of  s uch goods or construction \nworks or services, to create obstacles, in any mann er, to participation by \nqualified bidders in the procurement process or to limit competition without any \njustification.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Cost Estimate to be Prepared : (1) A Public Entity shall have to prepare a cost", "content": "estimate as prescribed for any procurement whatsoever.  \n Provided that a cost estimate shall not be require d for any procurement valuing \nup to twenty five thousand rupees.  \n(2) A Public Entity shall update as prescribed the cost estimate \nprepared pursuant to Sub-section (1).  \n 7", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Procurement Plan to be Prepared : A Public Entity shall, in making", "content": "procurement valued at an amount in excess of the pr escribed limit, have to \nprepare a master procurement plan and annual procurement plan, as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Responsibility Towards Procurement Activities:  (1) The chief of the", "content": "concerned Public Entity shall be responsible for pr eparing a procurement plan \npursuant to Section 6 and carrying out or causing t o be carried out all other \nactivities relating to procurement to be made by fu lfilling the procedures \nreferred to in this Act.  \n(2) A Public Entity shall, in carrying out procurem ent related activity \npursuant to Sub-section (1), carry out so through a n employee who has the \nqualification prescribed by the Public Procurement Monitoring Office and has \nknowledge or training on procurement business.  \n(3) A Public Entity shall establish a procurement u nit or assign the \nresponsibilities thereof in order to carry out the following acts:  \n(a)  Preparing a procurement plan,  \n(b)  Preparing prequalification documents, bidding documents and \nprocurement contract related documents by making ne cessary \namendments in the standard bidding documents, stand ard \nprequalification documents and standard procurement  contract \ndocuments prepared by the Public Procurement Monito ring \nOffice,  \n(c)  Preparing documents relating to proposals for consultancy \nservices by making necessary modification in the st andard \nrequest for proposal prepared by the Public Procure ment \nMonitoring Office,  \n(d)  Publicly publishing the procurement notice,  \n(e)  Issuing pre-qualification documents, bidding d ocuments or \n 8\nforwarding documents relating to proposals for cons ultancy \nservice,  \n(f)  Receiving and safely keeping pre-qualification  proposals, bids \nor consultancy service proposals,  \n(g)  Submitting the pre-qualification proposals, bi ds or consultancy \nservice proposals to the evaluation committee for e valuation \nand submit the evaluated bids for acceptance,  \n(h)  Notifying the acceptance of the pre-qualificat ion proposals, \nbids or consultancy service proposals,  \n(i)  Obtaining, examining and safely keeping the pe rformance \nguarantee,  \n(j)  Examining, or causing to be examined, the qual ity standards \nof the goods, construction works or services that h ave been \nprocured,  \n(k)  Making available the information and documents  asked for by \nthe Public Procurement Monitoring Office, and  \n(l)  Performing other functions as may be prescribe d.  \n(4) In carrying out  or causing to be carried out  the functions as referred \nto in Sub-section (3), the Procurement Unit or the unit to which responsibility \nthereof has been assigned shall carry out the same with the approval of the chief  \nof the concerned Public Entity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Procurement Method to be Selected : (1)  A Public Entity while procuring", "content": "shall have to procure by applying any of the follow ing methods based on such \nconditions and purchase price as prescribed:-  \n(a)  For procurement of goods, construction works o r other services:  \n (1) By inviting open bids at international level,  \n 9\n (2) By inviting open bids at national level,  \n (3) By inviting sealed quotations,  \n (4) By procuring directly,  \n (5) Through participation of users' committee or b eneficiary group,  \n (6) Through force account.  \n(b)  Procurement of consultancy service:  \n(1) By requesting competitive proposals,  \n(2) Through direct negotiations.  \n(2) In making procurement pursuant to this Act and the rules framed \nunder this Act, procurement shall not be so made in  piecemeal as to limit \ncompetition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Procurement to be Made by Inviting Open Bid", "content": ": Except as otherwise \nprovided in this Act, a Public Entity making   any procurement shall, to the \nextent possible, make by inviting open bids, and pr ovide equal opportunity to \nqualified bidders to participate in such procuremen t process without any \ndiscrimination.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Qualification of Bidder or Proponent : (1) A bidder shall have to fulfill the", "content": "following qualification in order to obtain a procurement contract:-  \n(a)  In the case of a bidder, the qualification cri teria set forth  in \nthe bidding documents or where prequalification  pr oceedings \nhave been conducted for procurement, the qualificat ion \ncriteria set forth in the prequalification documents , and   \n(b)   In the case of a consultant the qualification  criteria set forth in \nthe documents relating to proposals.  \n(2) In setting forth qualification criteria pursuant to Sub-section (1) in the \n 10 \nbidding documents or documents relating to proposal s, professional and \ntechnical qualifications, equipment availability, p ast performance, after-sale \nservice arrangements, availability of spare parts, legal capacity, financial \nresources and condition, punishment for having comm itted professional \noffenses and similar other criteria may be set forth.   \n(3) In setting forth the criteria pursuant to Sub-s ection (2), no provision \ncan be so made as to allow only a particular class of construction entrepreneur, \nsupplier, consultant or service provider to partici pate or to prevent any \nparticular class of construction entrepreneur, supp lier, consultant or service \nprovider from participating in the procurement process.  \n(4) Bids, pre-qualification proposals and consultan cy service proposals \nshall be evaluated only in accordance with the crit eria set forth in the bidding \ndocuments, pre-qualification documents and in the d ocuments relating to \nproposals, respectively, and such criteria shall eq ually be applicable to all \nbidders or proponents without any discrimination.  \n(5) Notwithstanding anything contained elsewhere in  this Section, no \nqualification requirements shall be prescribed for the procurement of a \nconstruction work the cost estimate of which is less than six million rupees.  \n(6) The Public Entity may disqualify a bidder or pr oponent at any time if \nit finds that the statement submitted by such bidde r or proponent concerning the \nqualifications was factually false or substantially incomplete.  \nProvided that minor errors can be corrected by seek ing information \npertaining thereto from the concerned bidder or proponent.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "11", "title": "Process and Stage of Bidding: (1)  In making procurement by bidding, an", "content": "invitation to bid can be made by the following process:-  \n 11 \n(a) Inviting open bids by determining prequalification,  \n(b) Inviting open bids without determining prequalification.  \n(2) The open bid may be invited in a single stage or in two stages.  \n(3) In making invitation to bid on the conditions s et forth in Sub-section \n(1) of Section 28, it may be made in two stages.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Prequalification to be Determined: (1) In order to procure such construction", "content": "work as determined by the Public Procurement Monito ring Office from time to \ntime to be large and complex, or to procure goods o f high value such as \nindustrial plants or with a view to identify qualif ied bidders, the Public Entity \nshall, prior to making invitation to bids, prepare prequalification documents and \npublicly invite to proposals for the determination of prequalification.  \n(2) Where the Public Entity considers appropriate, it may also determine \nprequalification for other procurement as well.  \n(3) The prequalification documents under Sub-sectio n (1) or (2) shall set \nforth the qualification criteria required for prequ alification and the method for \nthe preparation of proposal and the manner for the submission of proposal.  \n(4) The Public Entity shall provide as prescribed t he prequalification \ndocuments required to submit proposal as referred to in Sub-section (1) or (2) to \nall persons, firms, companies and organizations that request for such document.  \n(5) The selection of the qualified applicant shall be made on the basis of \nthe qualification criteria set forth in Sub-section  (3). The Public Entity shall \nopenly publish a list of the applicants so selected  and send the same to all \napplicants.  \n(6) If any applicant whose prequalification proposa l is rejected, requests \nfor the information of the reasons for the rejectio n of his or her proposal, within \nthirty days of the notice being given pursuant to S ub-section (5), the concerned \n 12 \nPublic Entity shall have to provide such information to him or her.  \n(7) Other provisions relating to the terms and cond itions of \nprequalification and determination thereof shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Bidding Documents to be Prepared: (1) Prior to invitation to bid, the Public", "content": "Entity shall have to prepare the bidding documents.  \n(2) The bidding documents under Sub-section (1) sha ll contain the \nfollowing matters:-  \n(a)  The nature of procurement, time required for p rocurement and \ntechnical specifications thereof,  \n(b)  Where bids are invited without carrying out pr equalification, \nthe criteria for qualification of bidders, as refer red to in \nSection 10,  \n(c)  Where there is provision of site visit, inform ation relating \nthereto,  \n(d)  If any bid conference has to be held prior to submission of bid, \ninformation relating to such conference,  \n(e)  Instructions for preparing and submitting bids , the place for \nthe submission of bids, the deadline for the submis sion of  \nbids and the place, date and time for the opening of bids,  \n(f)  Component of price, the currency or currencies  in which the \nbid price may be stated, the currency and the sourc e and date \nof the related exchange rate to be used for comparison of bids,  \n(g)  The criteria and methodology for the evaluatio n of bids and \nthe selection of bidder,  \n(h)  The preferences to be given, if any, for domes tic goods and \nlocal construction entrepreneurs, provision relating thereto,  \n 13 \n(i)  Where any goods or construction works are to b e procured by \nmaking separate lots and packages, such lots and packages and \nthe manner of evaluation thereof,  \n(j)  Where alternatives to the technical specificat ions are also \ninvited, the manner of evaluation of such alternatives,  \n(k)  Where a bid can be submitted even  only for a portion of the \ngoods, construction works or services to be procure d, a \ndescription of such portion or portions,  \n(l)  The validity period of bid,  \n(m)  The amount, type, acceptable form and validity  period of \nsecurity to be furnished for bid, performance or ot her \nnecessary matters,  \n(n)  Where a bid security is required, provision th at the period of \nthat security shall exceed by thirty days to the va lidity period \nof bid,  \n(o)  The terms and conditions of the procurement co ntract under \nSection 52 and the modality of coming for the entry  into force \nof that contract,  \n(p)  Information that bids shall not be processed i n the event of \nconflict of interest or information relating to leg al action for \nfraud or corruption,  \n(q)  Provision that any bidder may make an applicat ion, for \nreview, against any error or decision made by the P ublic \nEntity in carrying out bid proceedings,  \n(r)  Provision that the documents proving technical  capacity and \nfinancial proposal (bid price) have to be submitted  in one \n 14 \nenvelope, and  \n(s)  Such other matters determined by the Public Pr ocurement \nMonitoring Office as to be involved in the prequali fication \ndocuments or bidding documents.  \n(3) The Public Entity shall make available the bidd ing documents upon \ncollection of the charges as prescribed to any pers on, firm, organization or \ncompany that requests for the bidding documents in accordance with the notice \nfor invitation to bids, and where prequalification is required to participate in the \nprocurement proceedings, to those persons, firms, o rganizations or companies \nthat have been pre-qualified and request for such documents.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Invitation to Bids : (1) A notice for invitation to bids or prequalifica tion", "content": "proposals shall have to be published in a daily newspaper of national circulation \nand, in the case of an international bid; it may al so be published in any \ninternational communication media.  \n(2) The notice as referred to in Sub-section (1) sh all be placed in the \nwebsite of the concerned entity or that of the Publ ic Procurement Monitoring \nOffice, in the case of a central level Public Entit y, and in the case of a district \nlevel Public Entity, such notice may be placed in t he website of that body or \nthat of the Public Procurement Monitoring Office.  \n(3) A notice on invitation to bid or prequalificati on proposal shall \ncontain the following matters:-  \n(a)  The name and address of the Public Entity invi ting bid,  \n(b)  The nature of and time limit for procurement w ork and the \nplace of delivery of the goods to be supplied, the services to be \ndelivered and the construction work to be performed,  \n(c)  If bid security is required, the amount and va lidity period \nthereof,  \n 15 \n(d)   Where bid security is required, the amount an d validity period \nof the bid,  \n(e)  The place, manner of obtaining the bidding doc uments or \nprequalification documents, and the fees charged therefor,  \n(f)  The place, manner, the deadline for the submis sion or \nforwarding of the bidding documents or prequalifica tion \ndocuments,  \n(g)  The place, date and time for the opening of bi ds, and matter \nthat the bidders or their authorized agents shall b e invited to \nattend the opening of bid, and   \n(h)  Other matters as prescribed.  \n(4) In publishing a notice under Sub-section (1), for invitation of national \nlevel bidding or prequalification proposals, a peri od of at least thirty days shall \nbe given and at least forty five days shall be give n in the case of a notice on \ninvitation that of international level bidding or prequalification proposals.  \n(5) While stating the place from which the bidding documents or \nprequalification documents can be obtained pursuant  to clause (e) of Sub-\nsection (3), provision shall have to be made for ob taining such documents from \ntwo or more than two public entities.  \n(6) While stating the place for submitting or forwa rding the bidding \ndocuments or prequalification documents pursuant to  clause (f) of Sub-section \n(3), provision shall be made that such documents sh all be submitted or \nforwarded to only one Public Entity.  \n(7) Where any Public Entity, bidder or proponent re quests for security \nfor submitting or forwarding the bid or prequalific ation proposal pursuant to \nSub-section (6), the concerned District Administrat ion Office shall mandatorily \nmake security arrangements immediately.  \n 16 \n(8) In making procurement through an international level bidding, the \nPublic Entity may give domestic preference to the N epalese entrepreneurs and \nbusinesspersons as prescribed, and where domestic p reference is to be so given, \nthat matter shall be set forth in the notice on inv itation to bid and the bidding \ndocuments.   \nProvided that, in the case of procurement of constr uction work, \npreference may be given pursuant to Sub-section (1)  of Section 12 of the \nConstruction Entrepreneur Act, 1958.  \n(9) A foreign bidder, while submitting bid, shall h ave to state whether \nhe/she has appointed any agent in the State of Nepal or not.  \n(10) Where an agent is appointed pursuant to Sub-se ction (9), the details \nas prescribed in relation to the agent shall also be set forth in the bid.  \n(11) Notwithstanding anything contained elsewhere i n this Section, \nwhere a foreign bidder enters into joint venture wi th a domestic construction \nentrepreneur, in the case of procurement of public construction work, \npreference may be given to such a foreign bidder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "International Level Bidding : (1) While making invitation to bid pursuant to", "content": "this Act, an international level bid shall be invit ed in any of the following \nconditions:-  \n(a)  Where the goods or construction works as requi sitioned by a \nPublic Entity are not available under competitive p rice from \nmore than one construction entrepreneur or supplier  within the \nState of Nepal,  \n(b)  Where no bid was submitted in response to invi tation to  \nnational level bidding for the procurement of goods , \nconstruction works or other services, and the same has to be \nprocured from abroad,  \n 17 \n(c)  Where under an agreement entered into with a d onor party, \nforeign goods or construction works have to be proc ured from \nforeign assistance source,  \n(d)  Where the Public Entity has certified that the  goods or \nconstruction works, being of complex and special na ture, have \nto be procured through an international level bidding.  \n(2) A notice on invitation to international bidding  as referred to in this \nSection shall be published in English language; and  all bidding or \nprequalification documents shall have to be made av ailable in the English \nlanguage.  \n(3) The notice referred to in Sub-section (2) shall  have to be placed in \nthe website referred to in Sub-section (2) of Section 14.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Clarification as to Unclear Matter on Bidding o r Prequalification", "content": "Documents :(1) Where any bidder, being unclear about any matte r set forth in \nthe bidding documents or the prequalification docum ents, requests, within the \ntime period set out in such documents, for a clarif ication, the Public Entity shall \nhave to communicate the information of such matter to all bidders prior to the \ndeadline for the submission of bids or prequalification proposals.  \n(2) Where the Public Entity makes any alteration/mo dification in the \ninformation under Sub-section (1) and the bidding d ocuments or \nprequalification documents, it shall have to commun icate information relating \nto such alteration/modification to all bidders that  have participated in the \nprocurement proceedings within a reasonable time so  as to enable them to take \nsuch alteration/modification into account in submit ting their bids or preparing \ntheir proposals for prequalification.  \n(3) Where it is necessary to provide additional tim e to bidders for the act \nunder Sub-section (2), the Public Entity may extend  the deadline for the \n 18 \nsubmission of bids or prequalification proposals.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Deadline for Submission of Bids or Prequalific ation Proposals : The Public", "content": "Entity shall have to so set the deadline for the su bmission of bids or \nprequalification proposals as not to be less than t he period set forth in Sub-\nsection (4) of Section 14 and as to allow sufficien t time for bidders to prepare \nor submit such bids or proposals.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Method of Submission of Bids : (1) A bid shall have to be submitted in the", "content": "specified form, duly signed by the bidder himself / herself or his /her authorized \nagent, in a sealed envelope by the bidder himself / herself or through his or her \nauthorized agent or by post or courier at such plac e and within the last date and \ntime as specified for the submission of bids.  \n(2) Bids received after the deadline under Sub-sect ion (1) shall not be \nprocessed and such bid shall be returned unopened to the concerned bidder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Withdrawal and Modification of Bid : (1) A bidder may, prior to expiry of the", "content": "deadline for the submission of bids, make a sealed application for modification \nto or withdrawal of bid that a bidder has once submitted.  \n(2) Other provisions relating to the withdrawal or modification of bid \nshall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Validity Period of Bid : (1) The validity period of a bid shall be as specif ied in", "content": "the bidding documents.  \n(2) The period as referred to in Sub-section (1) sh all commence from the \ndeadline for the submission of bids.  \n(3) Notwithstanding anything contained in Sub-secti on (1), the Public \nEntity may, if so required to extend the validity p eriod of bids after the opening \nof bids, extend the validity period of bids as requ ired assigning the reasons for \nthe same.  \n 19 \n(4) In extending the validity period of bid pursuan t to Sub-section (3), \nconsent of the concerned bidder shall have to be obtained.  \n(5) A bidder who agrees to extend the validity peri od of his/her/its bid \npursuant to Sub-section (4) shall correspondingly e xtend the validity period of \nbid security.  \n(6) The bid security of the bidder not providing co nsent pursuant to Sub-\nsection (4) shall be returned.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Bid Security : (1) A bidder shall provide as prescribed bid securi ty along with", "content": "the bid.  \n(2) The security furnished pursuant to Sub-section (1) shall be forfeited \nin the following conditions:-  \n(a)  If the bidder requests for modification or wit hdrawal of bid \nduring the validity period of bid, after the deadli ne for the \nsubmission of bids,  \n(b)  If the bidder refuses to accept the correction  of arithmetical \nerrors found in the bid,  \n(c)  If the selected bidder fails to sign the procu rement contract in \naccordance with the terms and conditions set forth in the \nbidding documents,  \n(d)  Where the bidder fails to furnish the performa nce security as \nset forth in the bidding documents within the time for signing \nthe procurement contract,  \n(e)  If the bidder has changed the bid price or sub stantive matter of \nthe bid while providing any information in response  to \nclarification sought by the Public Entity pursuant to Sub-\nsection (4) of Section 23 in the course of examination of bids.  \n 20 \n(f)  If any act contrary to conduct as referred to in Section 62 is \ncommitted.  \n(3) After the conclusion of a procurement contract under Section 52, the \nPublic Entity shall return the bid security of the bidder who has signed the \nprocurement contract and the bid security of those bidders whose bid security is \nnot liable to forfeiture pursuant to Sub-section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Opening of Bids : The Public Entity shall have to open bids as prescr ibed at the", "content": "time and place specified in the bidding documents on the same day immediately \nafter expiry of the deadline for the submission of bids.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Examination of Bids : (1) The Public Entity shall have to submit to the", "content": "evaluation committee the bids opened pursuant to Section 22.  \n(2) The committee shall, prior to evaluating the bi ds submitted pursuant \nto Sub-section (1), examine the bids in order to ascertain the following matters:-  \n(a)  Whether documents establishing that the bidder  is qualified \nunder law to submit the bid are submitted or not,  \n(b)  Whether the bid is complete in accordance with  the \ninstructions to bidders set forth in the bidding  d ocuments or \nnot and whether it is signed by the bidder or by th e bidder’s \nauthorized agent or not,  \n(c)  Where a bid security is required to be submitt ed along with the \nbid, whether a bid security of such type, period an d amount as \nset forth in the bidding documents is accompanied w ith the bid \nor not,  \n(d)  Whether the bid is substantially responsive to  the technical \nspecifications set forth in the bidding documents a nd the terms \nand conditions of procurement contract attached wit h the \nbidding documents or not.  \n 21 \n(3) In examining the completeness of bids pursuant to clause (b) of Sub-\nsection (2), the following matters shall be examined:-  \n(a)  Whether a power of attorney for the authorized  agent or local \nagent of the bidder is submitted or not,  \n(b)  Where a joint venture agreement is necessary, whether such \nagreement is submitted or not,  \n(c)  Whether documents establishing the eligibility  of the bidder \nand of goods mentioned by the bidder are submitted or not,  \n(d)  Whether necessary document relating to the qua lifications of \nthe bidder is submitted or not,  \n(e)  Where the bidding documents require the submis sion of a rate \nanalysis, whether such rate analysis is submitted or not,  \n(f)  Other matters as prescribed.  \n(4) The Public Entity may, in the course of examini ng the bids pursuant \nto this Section, ask bidders for necessary information.  \n(5) The concerned bidder shall have to provide the information sought by \nthe Public Entity pursuant to Sub-section (4) to th e Public Entity, and in \nproviding such information, no change or alteration  in the bid price or other \nsubstance of the bid shall be allowed.  \n(6) In examining bids invited after determination o f prequalification, \nexamination of the qualification of bidder shall be  made to ascertain whether or \nnot it conforms to the prequalification or not.  \n(7) While examining the qualification pursuant to S ub-section (6), if the \nqualification of a bidder is found to be substantia lly lower than what was at the \nprequalification stage, the bid of such a bidder shall be rejected.  \n(8) If any arithmetical error is found in a bid in examining bids pursuant \n 22 \nto this Section, the Public Entity may correct such  an error, and where, in \nmaking such correction, there exists a discrepancy between unit rate and total \namount, the unit rate shall prevail, and the total amount shall be corrected as per \nthe same rate.   \n(9) Where there is a discrepancy between figures an d words in a bid \nsubmitted by a bidder, the amount in words shall prevail.  \n(10) Where any error is corrected pursuant to Sub-s ection (8) or (9), \ninformation of such correction shall be communicated to the concerned bidder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Non–procession of Bids : Bids having following noncompliance shall not be", "content": "processed:  \n(a)  Where it is not sealed,  \n(b)  Where it is not submitted within the time fram e,  \n(c)  The bids withdrawn pursuant to Section 19,  \n(d)  If it is not in accordance with Sub-section (2 ) of Section 23,  \n(e)  The bids submitted by mutual collusion pursuan t to Sub-section (6) \nof Section 26,  \n(f)  The bids cancelled pursuant to Sub-section (7)  of Section 23.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Evaluation of Bids", "content": ": (1) All submitted bids other than those separated f or non-\nprocession pursuant to Section 24, shall be included for evaluation.  \n(2) Where a bid is found containing minor deviation s in the matters such \nas the technical specifications, descriptions and c haracteristics etc. so as not to \nreject the bid, the value of such deviations shall be quantified, to the extent \npossible, and included in the evaluation of bids pursuant to Sub-section (1).  \n(3) Where the value of minor deviations under Sub-s ection (2) exceeds \nfifteen percent of the bid price of the bidder, suc h a bid shall be deemed to be \nsubstantially non-responsive; and shall be excluded from evaluation.  \n 23 \nExplanation : For the purposes of this Section, the words “minor  \ndeviations” mean such deviations that do not materi ally depart from the matters \nsuch as the technical specifications and descriptio ns as set forth in the bidding \ndocuments.  \n(4) Where invitation to bid has been made after det ermination of \nprequalification, the bids submitted by the bidder other than the pre-qualified \nbidders shall be excluded from evaluation under Sub-section (1).  \n(5) Bid shall be evaluated in accordance with the c riteria and \nmethodology set forth in the bidding documents; and  in carrying out such \nevaluation, the bid with the lowest bid price shall  be determined by making \ncomparison of the evaluated price of every bid with  the evaluated price of the \nother bids.  \n(6) The qualifications of the bidder of the bid hav ing  the lowest bid \nprice under Sub-section (4) shall be verified in or der to ascertain whether it \nconforms to the qualification criteria set forth in the bidding documents or not.  \n(7) Where on examination, the qualification of the bidder of the bid \nhaving the lowest bid price pursuant to Sub-section (4) is in conformity with the \nqualification evaluation criteria set forth in the bidding documents under Sub-\nsection (5), such bid shall be the lowest evaluated  substantively responsive bid. \nWhere, on examination, the qualification of such bi dder is found not to be in \nconformity with the qualification as evaluation cri teria set forth in the bidding \ndocuments, such bid shall be excluded from evaluati on; and the qualification of \nthe next bidder having the next lowest bid price sh all be examined on the same \ngrounds respectively.  \n(8) The evaluation committee shall prepare an evalu ation report stating, \ninter alia , the criteria and methodology of evaluation of the  lowest evaluated \nsubstantially responsive bid pursuant to Sub-sectio n (6) and submit the report to \n 24 \nthe Public Entity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Rejection of Bids or Cancellation of Procureme nt Proceedings : (1) The", "content": "Public Entity may, in the following circumstances, reject all bids or cancel the \nprocurement proceedings:-  \n(a)  If none of the bids are substantially responsi ve pursuant to \nclause (d) of Sub-section (2) of Section 23,  \n(b)  If the bid price of the lowest evaluated subst antially \nresponsive bid is substantially above the cost estimate, or  \n(c)  If requisitioned goods, construction works, co nsultancy \nservices or other services are no longer required.  \n(2) Notwithstanding anything contained in Sub-secti on (1), no bid shall \nbe rejected or re-bidding shall be invited only for  the reason that only a few \nbids are or only one bid is substantively responsive.  \n(3) The Public Entity shall have to communicate to all the bidders a \nnotice along with the reason for the rejection of b ids or cancellation of the \nprocurement proceedings pursuant to Sub-section (1).  \n(4) Where any bidder requests, within thirty days o f the communication \nof notice pursuant to Sub-section (3), for grounds for the rejection of all bids or \nrejection of the procurement proceedings, the Publi c Entity shall have to \ncommunicate such information to that bidder.  \n(5) In making re-invitation to bid because of non-s ubmission of any bid \nin response to an invitation to bid or cancellation  of all bids or cancellation of \nthe bid proceedings pursuant to Sub-section (1), th e modification shall also be \ncarry out in the bidding documents, technical speci fications, cost estimate and \nterms and conditions of procurement contract as per  necessity by reviewing the \nreasons for such rejection of bids or cancellation of the bid proceedings  \n 25 \n(6) Notwithstanding anything contained elsewhere in  this Section, if is \nproved that the bidder has submitted bid by collusi on among the bidders, such \nbid shall be rejected.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Acceptance of Bid and Procurement Contract : (1) The Public Entity shall", "content": "select for acceptance only the lowest evaluated sub stantially responsive bid in \naccordance with Section 25.  \n(2) Within seven days of the selection of the bid p ursuant to Sub-section \n(1), the Public Entity shall serve a notice of the intent of acceptance of his or \nher bid to the concerned bidder. Information regard ing the name, address of the \nbidder whose bid has been so selected and the price  of the bid shall also be \ncommunicated to the other bidders.  \n(3) If no bidder makes an application pursuant to S ection 47 within a \nperiod of seven days of providing the notice under Sub-section (2), the bid of \nthe bidder selected pursuant to Sub-section (1) sha ll be accepted and a notice \nshall be communicated to the bidder to furnish the performance security to \nconclude the procurement contract within fifteen days.  \n(4) The concerned bidder shall have to furnish the performance security \nand sign the procurement contract under Section 52 within the period set forth \nin Sub-section (3).  \n(5) If the bidder fails to furnish the performance security and sign the \nprocurement contract within the period under Sub-se ction (3), the bid security \nof that bidder shall be forfeited, and the bid of t he other immediately next \nlowest evaluated substantially responsive bidder sh all be accepted and the \nprocurement contract concluded.  \n(6) If even the bidder under Sub-section (5) fails to furnish the \nperformance security and sign the procurement contr act, the bid of the other \nimmediately next lowest evaluated substantially res ponsive bidder, \n 26 \nrespectively, shall be accepted, and a notice shall  be served to that bidder for \nconcluding the procurement contract pursuant to this Section.  \n(7) If, within thirty days of the communication of the notice as referred \nto in Sub-section (2), any bidder whose bid has bee n rejected requests for \ngrounds for the rejection of its bid, the Public En tity shall have to communicate \nsuch information to that bidder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Two-Stage Bidding: (1) Two-stage biding may be invited in the followin g", "content": "conditions:-  \n(a)  When it is not feasible to define fully the te chnical aspects of \nthe goods or construction works or services to be p rocured or \nthe terms and conditions of the procurement contrac t at the \ntime of the invitation to bid, or  \n(b)  Because of the complex nature of the goods or construction \nworks or services to be procured, if it is necessar y for the \nPublic Entity to discuss with the bidders about how  to resolve \nthe problems related to various technical aspects o r the \nprocurement contract and about such technical aspec ts and \nconditions of contract and benefits accruing there from.  \n(2) While inviting the first stage bid pursuant to this Section, the bidding \ndocuments shall state the purpose of procurement, e xpected performance, broad \nspecifications and other broad features and the qua lification of bidders, and \nstate that bidder shall not be required to quote th e price in his/her bid and shall \nsubmit only technical proposal and comments on the terms and conditions of \nthe proposed procurement contract.  \n(3) The Public Entity may hold discussions with any  or all bidders in \nrelation to the bids submitted in response to the i nvitation to bid made pursuant \nto Sub-section (2).  \n 27 \n(4) The Public Entity may, also taking into account  the discussions held \nin pursuance to Sub-section (3), do the following i n relation to the bids \nsubmitted pursuant to Sub-section (2):  \n(a)  Canceling a proposal relating to a bid that fa ils to meet the \nbasic requirements required to be met in relation t o \nprocurement or fails to make minimum performance or  fails to \ncomplete the work within the specified period or th at cannot \nbe modified to meet such requirements or to make su ch \nperformance or to complete the work within the spec ified \nperiod or due to any other weakness,  \n(b)  Modifying or improving the technical specifica tions, \nevaluation criteria and terms and conditions of the  \nprocurement contract in order to increase competition,  \n(c)  Determining the evaluation system in order to determine the \nappropriateness of various options submitted by the bidders.  \n(5) After the completion of the acts as referred to  in Sub-section (4), the \nPublic Entity shall make invitation to second stage  bid. In making such \ninvitation to bid, the bidders whose bids have not been cancelled pursuant to the \nsaid Sub-section shall be invited to submit bid alo ng with price in accordance \nwith revised bidding documents.  \n(6) The second-stage bidding proceedings to be carr ied out pursuant to \nSub-section (5) shall be carried out pursuant to th e provisions contained in this \nChapter except for those provided for in this Section.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "29", "title": "Consultancy Services  May be Procured: (1) A Public Entity may procure", "content": "consultancy services from any person, firm, organiz ation or company in the \n 28 \nfollowing conditions:-  \n(a)  If any work cannot be performed by the human r esource available \nat the concerned Public Entity, or  \n(b)  If a service is required to be obtained from a  consultant under the \nforeign aid source in accordance with an agreement with a donor \nparty.  \n(2)  In procuring the consultancy services under Su b-section (1), \nprocurement shall be made by fulfilling the procedures referred to in this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Short List to be Prepared by Soliciting Expres sion of Interest Openly : (1)", "content": "Where it is required to procure consultancy service  that costs more than the \nprescribed threshold, the Public Entity, in order t o solicit expression of interest \nfrom the persons, firms, organizations or companies  that are interested in \nproviding such consultancy services shall publish a  notice in a newspaper of \nnational circulation, giving a period of at least f ifteen days, setting out the \nmatters as prescribed.  \n(2) The notice under Sub-section (1) may be placed in the website of the \nconcerned Ministry of the Public Entity or of the P ublic Procurement \nMonitoring Office.  \n(3) International level expression of interest shal l have to be invited in \nthe following circumstances:-  \n(a)  To procure consultancy service, the cost of wh ich exceeds the \nprescribed threshold,  \n(b)  If the consultancy service as requisitioned by  the Public Entity \nis not available under competitive price from more than one \nconsultant within the State of Nepal,  \n(c)  If no proposal has been submitted in response to invitation to \n 29 \nnational level proposal for the procurement of cons ultancy \nservice, and the service has to be procured from an y foreign \nconsultant,  \n(d)  If it is necessary to obtain services from a c onsultant under the \nforeign aid source by soliciting international expr ession of \ninterest in accordance with an agreement with the donor party.  \n(4) While soliciting expression of interest under S ub-section (3), notice \nshall have to be published in English language.  \n(5) The Public Entity shall, upon evaluation, inter alia , of the \nqualification, experience and capacity of the inten ding proponents the \nexpression of interest pursuant to Sub-section (1) or (3), make selection of \ngenerally three to six intending proponents and who  can provide such \nconsultancy service, and prepare a short list as prescribed.  \n(6) Where it is required to procure consultancy ser vice the cost of which \nis less than the prescribed threshold, the Public E ntity may prepare a list of the \nperson, firm, organization or company that can prov ide such service, by \nfulfilling the procedures as prescribed, and shall solicit proposals pursuant to \nSection 31 from the person, firm, organization or c ompany that have been \nincluded in that list, by fulfilling the procedures as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Soliciting Proposals : (1) After a short list has been prepared pursuant t o", "content": "Section 30, the Public Entity shall request for pro posals from intending \nproponents, by giving a period of at least thirty d ays, sending the documents \nrelating to proposal, as prescribed to the intendin g proponents who are short \nlisted.  \n(2) The documents relating to proposal under in Sub -section (1) shall \ncontain the following matters:-  \n(a)  The name and address of the Public Entity,  \n 30 \n(b)  The nature of the services to be procured, the  time and place \nwhen and where the services are to be provided, the  terms of \nreference of the services, the task to be completed  and \nexpected outputs,  \n(c)  Instructions to proponent to prepare proposal,   \n(d)  Matters that the technical and the financial p roposals have to \nbe sealed in separate envelopes, each of which has to clearly \nindicate the type of  proposal outside it and that both \nenvelopes have then to be sealed in a separate enve lope and \nthat the required services have to be mentioned thereon,  \n(e)  Technical and financial evaluation weightage,  \n(f)  The criteria and weightage marks for the evalu ation and \ncomparison of proposal,  \n(g)  Conditions of the procurement contract,  \n(h)  The place, date and time for the submission of  proposals,  \n(i)  Method for the selection of proposals,  \n(j)  Statement that proposals shall not be processe d in the event of \nconflict of interest and information relating to le gal action if \nfraud or corruption is committed,  \n(k)  Provision that a proponent may make an applica tion for \nreview, against any error or decision made by the P ublic \nEntity in carrying out proposal proceedings, and  \n(l)  Other matters as prescribed.  \n(3) In setting forth in the documents relating to p roposals under Sub-\nsection (1), the criteria for the evaluation of pro posal pursuant to clause (f) of \nSub-section (2), any or all of the following criter ia shall be set forth as required \n 31 \nfor the evaluation of technical proposal:-  \n(a)  Experience of consultants in the task to be pe rformed by \nconsultants,  \n(b)  The quality of proposed methodology for the pe rformance of \ntask by the consultants,  \n(c)  The qualification of the proposed key human re source,  \n(d)  Provision of knowledge and technology transfer ,  \n(e)  In the case of international level proposals, the details of key \nNepalese human resource proposed for the performanc e of \ntask.  \n(4) In setting forth in the documents relating to p roposals under \nSub-section (1), the method for the selection of pr oposal pursuant to \nclause (i) of Sub-section (2), there shall be set f orth which of the \nfollowing methods shall be used for the selection of proposals:-  \n (a)      Quality and cost method,  \n(b)  Quality method,  \n(c)  Fixed Budget method, or  \n(d)  Least cost method.  \n(5) Notwithstanding anything contained in Sub-secti on (4), where the \nnature of the consultancy services to be procured i s exceptionally complex or \nsuch services are likely to have considerable impac t on future projects or \nnational economy, the selection of proposals may be  made exclusively on the \nbasis of the quality method, as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Opening of Proposals", "content": ": (1) After the expiry of the deadline for the submis sion \nof proposal, the outer envelope of the proposal rec eived from the proponent \nshall be opened and the sealed envelope of technica l and financial proposal \n 32 \nshall be separated.  \n(2) Out of the envelope separated pursuant to Sub-s ection (1), the \ntechnical proposals shall be opened first, and the envelope of financial proposal \nshall be kept safely apart unopened.  \n(3) The envelope of financial proposal separated pu rsuant to Sub-section \n(2) shall be opened only after making evaluation of  the technical proposal \npursuant to Section 33.  \n(4) Other provision relating to the opening of technical proposals shall be \nas prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Evaluation of Technical Proposal : The technical proposal shall be evaluated", "content": "in accordance with the evaluation criteria as presc ribed in the documents \nrelating to proposal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Opening of Financial Proposal : The financial proposals of only those", "content": "proponents who have been qualified from the evaluat ion of technical proposals \nshall be opened as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Evaluation of Financial Proposal:  The financial proposal opened pursuant to", "content": "Section 34 shall be evaluated as provided hereunder:-  \n(a)  Where quality and cost method is applied to se lect the \nproposal, the technical and financial proposals sha ll be \nevaluated in a combined form and the proposal of th e \nproponent who obtains the highest marks in such eva luation \nshall have to be selected as prescribed.  \n(b)  Where quality method is applied to select prop osal, only the \nproposal of the proponent obtaining the highest mar ks in the \ntechnical proposal shall have to be selected.  \n(c)  Where fixed budget method is applied to select  proposal, a \n 33 \nproposal having cost above such budget ceiling shal l be \nrejected and the proposal of the proponent who obta ins the \nhighest technical marks after falling within such b udget \nceiling shall have to be selected.  \n(d)  Where least cost method is applied to select p roposal, the \nproposal of a proponent having the lowest cost out of the \nproponents having obtained minimum marks prescribed  for \nbeing successful in the technical proposal shall ha ve to be \nselected.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Rejection of Proposal and Cancellation of Proc urement Proceedings : (1)", "content": "The Public Entity may reject all proposals or cance l the procurement \nproceedings in the following conditions:-  \n(a)  If all the received proposals are not substant ially responsive to \nthe terms of reference,  \n(b)  If the cost offered by the selected proponent is substantially \nmore than the cost estimate and available budget,  \n(c)  If the consultancy service is no longer requir ed or,  \n(d)  If it is proved that the proponents have submi tted the proposal \nby mutual collusions.  \n Provided that the proposal of those proponents who  have not \ncolluded may be processed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Negotiations with the Proponent:  (1) Negotiations with the proponent", "content": "selected pursuant to Section 35 may be held in the matter of terms of reference \nand scope of the proposed services, progress report , and facility to be made \navailable by the Public Entity.  \n(2) Except in the conditions under clause (b) of Su b-section (1) of \n 34 \nSection 35, negotiations in relation to the financial proposal cannot be held with \nrespect to the remuneration of professional experts.  \nProvided that negotiations may be held with respect  to the reimbursable \nexpenditure.  \n(3) If an agreement acceptable to both the Public E ntity and the \nproponent could not be resulted from the negotiatio ns held pursuant to this \nSection, the Public Entity shall have to negotiate in the case of the proposal \nunder clause (a) (b) and (c) of Sub-section (1) of Section 35, with the proponent \nhaving obtained the next highest marks and in the c ase of the proposal under \nclause (d), with the proponent having the next lowest cost, respectively.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Procurement Contract to be Concluded : (1) The proposal of the proponent", "content": "who has reached to the agreement from the negotiati ons pursuant to Section 37 \nshall be selected for acceptance.  \n(2) Within seven days of selection of proposal purs uant to Sub-section \n(1), the Public Entity shall have to serve a notice  of the intention of accepting \nthe proposal to the proponent so selected and to other short-listed proponents.  \n(3) If no proponent files an application pursuant t o Section 47 within \nseven days of a notice being served pursuant to Sub -section (2), the proposal of \nthe proponent selected pursuant to Sub-section (1) shall be accepted and s/he \nshall be served a notice by giving a period of fift een days to come to sign the \ncontract.  \n(4) If the proponent attends within the period unde r Sub-section (1) to \nconclude contract, s/he shall have to sign contract  under Section 52, and if s/he \ndoes not attend, the Public Entity shall hold negot iations, respectively, pursuant \nto Section 37 with the proponent having obtained ne xt higher marks in the case \nof a proponent under clause (a), (b), and (c) of Su b-section (1) of Section 35 \nand with the next proponent having the lowest cost in the case of clause (d) and \n 35 \nconclude contract with such proponent pursuant to Section 52.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Other Provision for Consultancy Services : Other procedure concerning", "content": "procurement of consultancy service and evaluation p rocess thereof shall be as \nprescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "40", "title": "Provision Relating to Sealed Quotation:  (1) The threshold of the amount of", "content": "the goods, construction work or other services that  can be procured through \nsealed quotation shall be as prescribed.  \n(2) Before inviting a sealed quotation, a form of s ealed quotation stating \nclearly therein the specifications, quality, quanti ty terms and conditions of \nsupply and time and other necessary matters of the goods, construction work or \nother services to be procured shall have to be prepared.  \n(3) In inviting a sealed quotation, a notice shall be published in a \nnational or local level newspaper by giving a period at least of fifteen days.  \n(4) The sealed quotation, once submitted, cannot be  withdrawn or \namended.  \n(5) The lowest evaluated sealed quotation falling w ithin the cost estimate \nafter fulfilling the terms and conditions under Sub -section (2) shall have to be \napproved.  \n(6) Other provisions of sealed quotation shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Provision for Direct Procurement : (1) Notwithstanding anything contained", "content": "elsewhere in this Act, goods or consultancy service s or other services may be \ndirectly procured  or construction work may be caus ed to be carried out directly \nin the following conditions:-  \n(a)  Low-value procurement valuing up to the prescr ibed amount,  \n 36 \n(b)  If only one supplier or construction entrepren eur or consultant \nor service provider has the technical efficiency or  capacity to \nfulfill the procurement requirement,   \n(c)  If only one supplier has the exclusive right t o supply the goods \nto be procured and no other appropriate alternative  is \navailable,  \n(d)  If additional goods or services of proprietary  nature within the \nprescribed limit is to be procured from the existin g supplier or \nconsultant or service provider after it has been pr oved that if \nthe existing supplier or consultant or service prov ider is \nchanged to replace or extend existing goods or serv ices or the \nspare parts of the installed machine the goods or s ervices \nexisting in the Public Entity can not be replaced or changed,  \n(e)  If the most necessary construction works, good s or \nconsultancy services or other services within the l imit as \nprescribed but not included in the initial contract  due to failure \nto foresee and difficult to be completed by separat ing from the \ninitial contract due to technical or financial reas ons, is to be \nprocured.  \n  \n(f)  If the service of a particular consultant with  his unique \nqualifications is immediately needed for the concer ned work \nor where the service of same consultant is indispensable.  \n(2) Notwithstanding anything contained elsewhere in  this Section, \nprocurement to be made pursuant to clause (b), (e) and (f) shall be made in the \ncase of the Public Entity under sub-clause (1) of c lause (b) of Section 2 as per \nthe decision of Government of Nepal, Council of Min isters, on recommendation \n 37 \nof the following committee and in the case of other  Public Entity as per the \ndecision of the supreme executive body of that entity:-  \n(a)  Chief Secretary, Government of  Nepal  -Coordinator  \n(b)  Secretary, Ministry of Finance  -Member  \n(c)  Secretary, Concerned Ministry  -Member  \n(d)  Financial Comptroller General     -Member  \n(e)  Chief, Public Procurement Monitoring Office  -Membe r  \n(3) For the direct procurement pursuant to Sub-sect ion (1), the Public \nEntity shall invite written rate or proposal from o nly one supplier or \nconstruction entrepreneur or consultant or service provider after preparing a \nwritten description as prescribed of the special ma tter concerning its \nrequirements and quality, quantity, terms and condi tions and time of supply and \nmay procure by holding negotiations according to necessity.  \nProvided that such procurement shall be made only a fter obtaining prior \napproval where an approval is required under this A ct and by concluding a \ncontract.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Special Provision Relating to Ration Procurem ent  : (1) Notwithstanding", "content": "anything contained elsewhere in this Act, the Publi c Entity in procuring ration, \nshall have to apply the procedure as prescribed in the following matters:-  \n(a) Cost estimate and approval thereof,  \n(b) Price-escalation,  \n(c) Bidder's eligibility,  \n(d) Bid security,  \n(e) Submission of bid, and  \n(f) Other matter as prescribed.  \n 38 \n(2) Procedures other than those mentioned in Sub-se ction (1) shall be as \nprovided for in this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Provision Relating to Renting House and Land a nd Obtaining Service on", "content": "Contract:  Notwithstanding anything contained elsewhere in th is Act, the \n Public Entity may take house and land on rent or o btain the prescribed services \n on contract in compliance with the prescribed proc edure.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Construction Works May be Caused to be Carried  out  by Users", "content": "Committee or Beneficiary Community : If economy, quality or sustainability \nis increased in having a construction work carried out or obtaining services \nrelated thereto from the users committee or benefic iary community or if the \nmain objective of the project is to create employme nt and to have the \nbeneficiary community involved, such work may be ca used to be carried by or \nsuch service may be obtained from a users' committe e or beneficiary \ncommunity by fulfilling the procedure as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Works May be Done or Cause to be Done by Force  Account:  (1)  Such work", "content": "as repair and maintenance of ordinary nature, regul ar petty work or sanitation \nmay be done by force account or caused to be done by a users' committee.  \n(2) The procedure to be applied for carrying out or  causing to be carried \nout the work pursuant to Sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Work May be Caused to be Carried Out by Non-Governm ental", "content": "Organization:  (1) If promptness, effectiveness and economy are ac hieved in \nhaving works such as public awareness training, ori entation, empowerment, \nmain-streaming carried out by a non-governmental or ganization, the Public \nEntity may have such work carried out or obtain suc h services from a non-\ngovernmental organization by application of the process as prescribed.   \n \n  \n 39", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "47", "title": "Application may be Filed before the Chief of P ublic Entity :  (1) A bidder or", "content": "proponent may file an application before the chief of the concerned Public \nEntity for review against any error or decision made by the Public Entity stating \nthe cause for the damages the bidder will suffer or  is likely to suffer from the \nerror or breach of the duty, imposed on the Public Entity in carrying out the \nprocurement proceedings or making decision.  \n(2) The application to be filed pursuant to Sub-sec tion (1) shall be \nlimited with respect only to the proceedings prior to entry into force of the \nprocurement contract.  \n(3) The application under Sub-section (1) shall hav e to be filed within \nthe period specified, if any, in this Act for makin g application and, if not so \nspecified, within seven days from the date of the b idder or proponent having \nbecome aware of that the Public Entity has made an error or has dishonored the \nduty relating to the procurement proceedings.  \n(4) In the application under Sub-section (1), the a pplicant shall have to \nstate clearly the commission or omission of an act by the Public Entity that led \nto such error or breach of duty and the provision o f this Act or Regulations or \nguidelines made thereunder that have been contravened by such decision.  \n(5) An application for review received after the ex piry of the period \nunder Sub-section (3) shall not be processed.  \n(6) If, from the inquiry made in respect of the app lication received \npursuant to Sub-section (1), an error is found in t he procurement proceedings or \nthe Public Entity is found to have breached its dut y or such decision is found to \nbe contrary to law, the chief of the Public Entity shall suspend the procurement \nproceedings and make a decision with reason in writ ing within five days of \n 40 \nreceipt of such application.  \n(7) The decision under Sub-section (6) shall also s tate how the \nprocurement proceedings shall further proceed on.  \n(8) If the application under Sub-section (1) is in respect of the \nprocurement proceedings of an amount below the pres cribed one, no \napplication can be submitted before the Review Comm ittee for review against \nthe decision made by the chief of the Public Entity pursuant to Sub-section (6).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Review Committee : (1) For review of the application under Section 49,", "content": "government of Nepal shall constitute a public procu rement Review Committee \nconsisting of the following chairperson and member:-  \n  \n(a)  One person from among the former judges of the \nAppellate Court or Judge of the Appellate Court or the \npersons retired from the special class post of \nGovernment of Nepal.   \n \n-Chairperson  \n(b)  One person from among the persons retired from the \ngazetted first class post of the Nepal Engineering \nService of the Government of Nepal  \n \n-Member  \n(c)  One person from among the persons having \nexperiences and expertise on public procurement  \n \n-Member  \n(2) While making appointment of a member under clau se (c) of Sub-\nsection (1), no employee, currently holding a post in a Public Entity shall be \nappointed.  \n(3) The tenure of the chairperson or member appoint ed pursuant to Sub-\nsection (1) shall be three years.  \nProvided that in appointing the members for the fir st time, one member \n 41 \nshall be appointed for one year and the other member shall be appointed for two \nyears.  \n(4) The tenure of the chairperson or member under S ub-section (1) may \nbe extended up to another one term.  \n(5) The terms and conditions of the service and rem uneration and \nfacilities of the chairperson or member under Sub-s ection (1) shall be as \nspecified by the Government of Nepal.  \n(6) Before assuming the office, the chairperson or member under Sub-\nsection (1) shall have to submit the information of  the details as prescribed to \nthe Government of Nepal through the Public Procurement Monitoring Office.  \n(7) Government of Nepal may remove the chairperson or member in the \nfollowing conditions:-   \n(a)  If s/he commits misconduct,  \n(b)  If s/he fails to discharge the functions and d uties as per the \nresponsibility of the post due to lack of performan ce capacity \nor skill, or  \n(c)  If s/he is convicted guilty from a court of la w in a criminal \noffense of moral turpitude.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Application May be Filed Before the Review Com mittee", "content": ": A bidder or \nproponent may file an application for review before  the Review Committee in \nthe following conditions:-  \n(a)  If the chief of the Public Entity does not mak e a decision on \nthe application filed before the Public Entity purs uant to \nSection 47 in respect of the procurement proceeding s of the \namount above the prescribed threshold within the pe riod as \nreferred to in Sub-section (6) of the same Section or if the \n 42 \napplicant is dissatisfied with the decision made by him/her,  \n(b)  In the matter of the procurement contract conc luded pursuant \nto Section 52.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Method of Review : (1) A bidder or consultant filing an application fo r review", "content": "under Section 48 before the Review Committee shall have to file such \napplication in the case of clause (a) of Section 49  within seven days and in the \ncase of clause (b) of the same Section within a per iod of thirty days from the \ndate of conclusion of such contract.  \n(2) Within three days of the receipt of application  pursuant to Sub-\nsection (1), the Review Committee shall notify, by transmitting a copy of such \napplication and document attached to such applicati on, if any, to the concerned \nPublic Entity to provide the information about the action taken in that respect \nand comments thereon.  \n(3) Within three days of the receipt of notice purs uant to Sub-section (2), \nthe Public Entity shall have to provide to the Revi ew Committee with \ninformation and comments related thereto.   \n(4) The Review Committee shall have to make decisio n within thirty \ndays of receipt of the application pursuant to Sub- section (1) on the basis of the \ninformation and comments received pursuant to Sub-s ection (3), the evidence \nsubmitted by the applicant along with the applicati on and, if necessary, by \nhearing both the parties.  \n(5) In making a decision pursuant to Sub-section (4 ), the Review \nCommittee may decide as follows:-  \n(a)   Dismissing the application,  \n(b)  In the cases where procurement contract has no t been \nconcluded,-  \n 43 \n(1)   Giving an order to the Public Entity not to c ommit or \nmake an unauthorized act or decision or to pursue \nincorrect procedure,  \n(2)  Annulling the whole or in part an unauthorized  act or \ndecision made by the Public Entity,  \n(3)  If bids or proposals need to be re-evaluated d ue to \noccurrence of error in its evaluation, issuing an o rder \nfor re-evaluation, citing such error as well, if any, in the \nevaluation.  \n(c)  Where a procurement contract has already been concluded if \nthe Review Committee considers that such contract s hould \nhave been awarded to the applicant, recommending to  the \nPublic Entity to pay a reasonable amount (quantum m erit) to \nthe applicant having regard to the grievances suffe red by the \napplicant.  \n(6) An applicant filing application for review purs uant to this Section \nshall have to deposit security as prescribed.  \n(7) In cases where an application is dismissed purs uant to clause (a) of \nSub-section (5), such security shall be forfeited.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Procurement Proceedings to be Withheld", "content": ": (1) Upon receipt of the notice of \nthe application for review filed pursuant to Sub-se ction (1) of Section 50, the \nPublic Entity shall have to withhold procurement pr oceedings until the Review \nCommittee makes a decision in respect of such application.  \n(2) Notwithstanding anything contained in Sub-secti on (1), procurement \nproceedings need not be stopped in the following conditions:-  \n(a)  If the Public Entity informs the Review Commit tee certifying \nthe matter that there is an urgency to keep the pro curement \n 44 \nproceedings continuing due to an important public i nterest \nlying in the procurement proceedings, or  \n(b)  If the Review Committee fails to make a decisi on within the \nperiod under Sub-section (4) of Section 50,  \n(c)  Where the procurement contract has been conclu ded.  \n(3) If the Public Entity does not withhold the proc urement proceedings \npursuant to clause (a) and (b) of Sub-section (2), it shall have to give \ninformation thereof to the Review Committee.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "52", "title": "Procurement Contract and Terms and Conditions Thereof : (1) In making", "content": "procurement other than of low-value one, in accorda nce with this Act, the \nPublic Entity shall have to conclude a procurement contract in accordance to \nthis Section.  \n (2) The procurement contract under Sub-section (1)  shall include the \nterms and conditions as referred to in the bidding documents, documents \nrelating to proposal and documents relating to seal ed quotation and such terms \nand conditions may, according to the nature of the contract be the following:-  \n(a)  Name and address, telephone, fax number of the  parties to the \nprocurement contract and their contact person for \nimplementation of the contract,  \n(b)  Scope of the procurement contract,  \n(c)  Details of the documents included in the procu rement contract \nand their priority order,  \n(d)  Work performance schedule,  \n(e)  Supply time, performance time or whether time can be \n 45 \nextended or not,  \n(f)  Procurement contract amount or procedure of de termining it,  \n(g)  Terms and conditions for acceptance of goods, construction \nwork or services,  \n(h)  Terms and conditions and mode of payment inclu ding \npayment in advance, payment of foreign currency,   \n(i)  F orce majeure,  \n(j)  If price adjustment can be made, provision the reof,  \n(k)  If procurement contract can be amended and var iation order \ncan be issued, provision thereof,  \n(l)  If insurance is necessary, provision relating thereto,  \n(m)  Security required,  \n(n)  Liquidated damages for failure of performance within the \nstipulated time,  \n(o)  Provision concerning bonus to be given if work  is completed \nbefore the stipulated period,  \n(p)  Conditions in which procurement contract may b e terminated,  \n(q)  Provision whether sub-contract can be conclude d or not,  \n(r)  Mechanism for settlement of disputes,  \n(s)  Applicable law, and  \n(t)  Other matters as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Amendment to Procurement Contract", "content": ": Unless otherwise provide for in \nprocurement contract, a procurement contract may be  amended by written \nconsent of both the parties subject to non-alterati on of the basic nature or scope \n 46 \nof the work.  \nProvided that procurement contract need not be amen ded in issuing a \nvariation order pursuant to Section 54 or making pr ice adjustment pursuant to \nSection 55.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Variation Order : (1) Unless otherwise provided for in the procuremen t", "content": "contract, if the circumstances that could not be fo reseen at the time of signing \nof procurement contract arise in the course of impl ementation of the \nprocurement contract, the competent authority may, by stating clear reasons \nthereof, issue as prescribed, a variation order for  a variation of up to fifteen \npercent and for a variation order above it, a varia tion order may be issued as per \nthe decision made by the Government of Nepal Counci l of Ministers by \ncomplying with the procedure as prescribed in the c ase of the Public Entity \nunder sub-clause (1) of clause (b) of Section 2 and  in the case of other Public \nEntity as decided by the supreme executive body of such entity.  \n(2) The variation order under Sub-section (1) shall  be issued in the \nfollowing manner:-  \n(a)  To be so issued as not to change the basic nat ure or scope of \nthe concerned work,  \n(b)  There must have been made arrangements for bud get and,  \n(c)  Approval of the competent authority must have been obtained.  \n(3)  Other provision concerning the issuance of var iation order shall \nbe as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Price Adjustment in Procurement Contract : (1) Unless otherwise provided", "content": "in procurement contract, if price needs to be adjus ted in the course of \nimplementation of a procurement contract having dur ation exceeding fifteen \nmonths the competent authority may adjust price.  \n 47 \nProvided that where a procurement contract has been  concluded to \nprocure a public construction work following the in vitation of national level \nbidding and the price of any construction materials  is increased or decreased \nunexpectedly by more than ten percent of the previo us price, price shall be \nadjusted as prescribed by deducting ten percent in the amount so increased or \ndecreased.  \n(2) Notwithstanding anything contained in Sub-secti on (1), price \nadjustment cannot be made where the work under the contract is not completed \nwithin the period prescribed in such contract and has taken more time due to the \ndelay by the person who has obtained procurement co ntract or if procurement \ncontract is concluded on the basis of lump sum contract or fixed budget.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Provision Concerning Extension of Contract Per iod", "content": ": (1) Provisions \nconcerning the extension of period of procurement c ontract shall be as provided \nin the concerned procurement contract.  \n(2) Notwithstanding anything contained in Sub-secti on (1), if the period \nof procurement contract is to be inevitably extende d due to  force majeure , \nfailure of the Public Entity to make available the materials to be made available \nby it or other reasonable causes, the competent aut hority may extend the period \non the prescribed grounds upon submission of applic ation by the person \nobtaining procurement contract.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Payment of Bill or Invoice : Subject to the procurement contract, the Public", "content": "Entity shall have to make payment of the bill/invoice as prescribed", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Mechanism for Dispute Settlement : (1) Any dispute arising between the", "content": "Public Entity and the construction entrepreneur, su pplier, service provider or \nconsultant in connection with the implementation of  the procurement contract \nshall be settled amicably.  \n 48 \n(2) A procurement contract may provide the mechanis m for resolution of \ndisputes that could not be settled amicably in accordance with Sub-section (1).  \n(3) In providing mechanism for resolution pursuant to Sub-section (2), \nthe procurement contract may provide that any dispu te relating to supply of \ngoods, consultancy service and other services shall  be resolved through \narbitration in accordance with the procedure provid ed for, if any, in the \nprocurement contract and, if not provided for, in a ccordance with the prevailing \nlaw.  \n(4) In providing mechanism pursuant to Sub-section (2), the procurement \ncontract may provide that disputes relating to cons truction work shall be \nresolved as follows:-  \n(a)  By an adjudicator for an amount, as prescribed ,  \n(b)  By a three-member dispute resolution committee , in the case \nof amount exceeding that of clause (a).   \n(c)  The provision that if a person is not satisfie d with the decision \nmade under clause (a) or (b), such dispute shall be  resolved \nthrough arbitration pursuant to prevailing law.  \n(5) The appointment of adjudicator and formation of  dispute resolution \ncommittee under Sub-section (4), and their function s, duties and power and \nprocedure for resolution of dispute shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Termination of Procurement Contract and Remedy  Therefor :  (1) The", "content": "procurement contract shall have to specify the gro unds in which such contract \n may be terminated.  \n(2) The main grounds under Sub-section (1) may be the following:-  \n(a)  Grounds that the Public Entity may terminate p rocurement \ncontract if the supplier, consultant, service provi der or \n 49 \nconstruction entrepreneur breaches the procurement contract,  \n(b)  Grounds that the Public Entity may terminate t he procurement \ncontract on the grounds of convenience for public interest,  \n(c)  Grounds that a supplier, consultant, service p rovider or \nconstruction entrepreneur may terminate the procure ment \ncontract, and   \n(d)  Grounds that procurement contract may be termi nated for \nforce majeure.  \n(3) A procurement contract shall include along with  the following \nmatters the provision of financial settlement and c ompensation to be made in \nthe event of termination of the procurement contract:-  \n(a)  If payment is remaining to be made for the val ue of work, \nsupply or service that has already been satisfactor ily \ncompleted, payment thereof,  \n(b)  Liability to be borne by a defaulting supplier , consultant, \nservice provider or construction entrepreneur for t he increased \ncost to be incurred by the Public Entity to carryou t or cause to \nbe carried out the work under the procurement contract,  \n(c)  Amount of the actual loss sustained by the sup plier or \nconsultant or service provider or construction entrepreneur due \nto the termination of procurement contract by the Public Entity \nwithout any default on his/her part.  \n(4) Unless otherwise provided in the procurement co ntract, for public \ninterest, the Public Entity may terminate a procure ment contract on the grounds \nof convenience.  \n(5) Where a procurement contract has been terminate d pursuant to Sub-\n 50 \nsection (4), the Public Entity shall have to pay th e value for the following work \nthat has been completed prior to  the termination of the said contract :-  \n(a)  Payment due under clause (a) of Sub-section (2 ),  \n(b)  Where expenditure is to be paid on reimburseme nt basis, such \nexpenditure as actually incurred,  \n(c)  The price of the goods specially manufactured for the Public \nEntity under the procurement contract,   \n(d)  Excluding the lost profit and the amount under  clause (c) of \nSub-section (3), the expenditure incurred for termi nation of \nthe procurement contract, and  \n(e)  Other expenditure as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Public Notice of Procurement Contract : After a procurement contract has", "content": "been concluded pursuant to this chapter, the Public  Entity shall have to publish \nas prescribed a notice including the result of the evaluation of bid or \nconsultancy service.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": "Chapter-8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "61", "title": "Conduct of the Official Involved in Public Pro curement Proceedings : (1)", "content": "Any officials involved in the act of formulating pr ocurement plan, operating \nprocurement proceedings, implementing procurement c ontract or other act as \nprescribed relating to procurement of the Public En tity, shall have to follow the \nfollowing conduct:-  \n(a)   Discharging one's duty impartially so that bi dders fairly \ncompete in the procurement proceedings,  \n(b)  Operating procurement proceedings in public in terest,   \n(c)  Not committing an act conflicting interest wit h the \n 51 \nprocurement from his/her work or conduct or behavior,  \n(d)  Keeping confidential all proprietary informati on of the bidder \nknown by him /her in the course of the procurement \nproceedings,  \n(e)  Not working with a person, firm, organization,  company and \nany other institution of private nature with which s/he had had \ndealings of procurement at the time of holding post  for two \nyears after retirement,  \n(f)  If s/he knows that his/her nearest relatives h ave participated as \na bidder or proponent in the procurement proceeding s of \nhis/her involvement, not taking part in such procur ement \nproceedings by giving immediate notification to one  level \nhigher authority,  \nExplanation \n: For the purpose of this clause nearest relative  \nmeans husband, wife, father, mother, son, daughter of a joint \nfamily, mother-in-law, father-in-law, elder brother , younger \nbrother, elder sister, younger sister, son-in-law, sister-in-law \nor brother-in-law.  \n(g)  Not committing an act in contravention of prev ailing law, \nwhile carrying out procurement proceedings,  \n(h)  Not committing corrupt or fraudulent practice nor involving in \nsuch act,  \n(i)  Not colluding or involving in a group prior to  or after \nsubmitting bid or proposal with the objective of fo rbidding or \ncausing to be forbidden the benefit of competition.  \n  \n 52", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Conduct of Bidder or Proponent:   (1) A bidder or proponent shall have to", "content": "accomplish such obligation as referred to in this A ct or Regulations made \nthereunder, procurement contract and other documents relating to procurement.  \n(2) Without prejudice of the generalities of the pr ovision of Sub-section \n(1), a bidder or proponent shall not carry out or c ause to be carried out the \nfollowing act with the intention of making interfer ence in the procurement \nprocess or the implementation of procurement contract:-  \n(a)  Giving or offering directly or indirectly impr oper inducement,  \n(b)  Submitting a fact by distortion or misrepresen tation,  \n(c)  Engaging in corrupt or fraudulent practice or involving in such \nact,  \n(d)  Intervening in the participation of other comp eting bidder or \nproponent to be involved in any way in the proceedi ngs \nrelating to bid or proposal,  \n(e)  Commit an act of threatening directly or indir ectly to cause \nharm to the body, person or property of any person to be \ninvolved in the procurement proceedings or coercive act,  \n(f)  Making collusion or involving in groupism prio r to or after \nsubmission of bid or proposal with the objective of  allocating \nprocurement contract among the bidders or proponent s or \nfixing the price of bid or proposal artificially or  \nnoncompetitively or otherwise forbidding the Public  Entity of \nthe benefit of open and free competition,  \n(g)  Contacting the Public Entity from the time of the opening of \nbid or proposal until the notice of acceptance of b id or \nproposal is given with the objective of causing int erference \nupon bid or proposal or committing an act of interf erence in \n 53 \nthe examination or evaluation of bid or in the eval uation of \nproposal.   \n (3) A bidder responsible for preparing bidding doc uments or \nspecifications of a procurement contract or for sup ervising the implementation \nprocurement contract or a person or firm or organiz ation or company affiliated \nwith him/her, or an employee working in such firm o r organization or company \ncannot participate in the bidding proceedings of such procurement.  \nProvided that this provision shall not be applicabl e in the case of a turn \nkey procurement contract or procurement contract so  concluded as to carryout \nboth the design and construction work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Blacklisting and Exclusion From the Blacklist : (1) The Public Procurement", "content": "Monitoring Office may blacklist a bidder, proponent , consultant, service \nprovider, supplier, construction entrepreneur or ot her person, firm, organization \nor company in the following grounds from one year t o three years on the basis \nof seriousness of his/her/ act:-  \n(a)  If it is proved that s/he has committed an act  contrary to the \nconduct as referred to in Section 62,  \n(b)  If a proponent of a proposal selected for acce ptance does not \ncome to sign the contract pursuant to Section 38,  \n(c)  If it is proved latter that s/he had committed  substantial defect \nin implementing procurement contract or had not sub stantially \nfulfilled obligation under the contract or the work  carried out \naccording to the procurement contract is not of the  quality as \nper the said contract,  \n(d) If convicted from a court of law in a criminal offense liable to \nbe disqualified for taking part in procurement contract,  \n(e)  If s/he/it is proved of having signed the proc urement contract \n 54 \nby falsifying qualification or misrepresenting,  \n(f)  Any other conditions as prescribed.  \n(2) A bidder, proponent, consultant, service provid er, supplier, \nconstruction entrepreneur or other person, firm, or ganization or company \nblacklisted pursuant to Sub-section (1) shall be de barred from taking part in the \nprocurement proceedings of a Public Entity up to that period.  \n(3) Notwithstanding anything contained elsewhere in  this Section, a \nperson, firm, organization or company blacklisted b y a competent authority \nunder prevailing law for not paying a loan of a bank or financial institution shall \nnot be eligible to take part in the procurement pro ceeding of a Public Entity \nduring the period of such blacklisting.  \n(4) If the person, firm, organization or company in eligible to take part in \nthe public procurement proceedings pursuant to Sub- section (2) or (3) is found \nto have taken part in a procurement of a Public Ent ity, no action shall be taken \nover his/her bid or proposal.  \n(5) Other provision concerning blacklisting pursuan t to Sub-section (1) \nshall be as prescribed.  \n(6) A bidder, proponent, consultant, service provid er, supplier, \nconstruction entrepreneur or other person, firm, or ganization or company \nblacklisted pursuant to Sub-section (1), (2), (3), (4), and (5) shall be excluded \nfrom the blacklist as per the criteria prepared by the Public Procurement \nMonitoring Office for exclusion from the blacklist.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": "Chapter-9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "64", "title": "Public Procurement Monitoring Office : (1) A Public Procurement", "content": "Monitoring Office under the Office of the Prime Mi nister and Council of \n 55 \n Ministers shall be established in order to monitor  procurement activities,  \n(2) The chief of the office under Sub-section (1) s hall be an employee of \nthe gazetted special class of the civil service of Government of Nepal.  \n(3) Notwithstanding anything contained elsewhere in  this Section until \nthe Public Procurement Monitoring Office is establi shed pursuant to Sub-\nsection (1), the Office of the Financial Comptrolle r General may function as the \nPublic Procurement Monitoring Office for not exceeding six months.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Functions, Duties and Powers of Public Procure ment Monitoring Office  :", "content": "(1) The functions, duties and powers of the Public Procurement Monitoring \nOffice, in addition to the ones referred to elsewhe re in this Act, shall be as \nfollows:-  \n(a)  To make recommendation to the government of Ne pal for \nreform in the procurement policy or laws in force,  \n(b)  To issue technical guidelines and manuals requ ired for \nimplementing this Act,  \n(c)  To prepare standard model of the standard bidd ing documents, \nprequalification documents, procurement contract do cument \nand documents relating to proposal to be used by a Public \nEntity to conduct procurement proceedings,  \n(d)  To collect statistics of procurement proceedin gs to be operated \nor operated by a Public Entity and to monitor or to  make or \ncause to be made technical auditing of whether or n ot such \nproceedings are conducted in compliance with this A ct or \nRegulations or manual, made thereunder.  \n(e)  If the Public Entity seeks opinion, advice abo ut a matter as \nreferred to in this Act or Regulations, Manuals mad e there- \nunder, to provide opinion, advice,  \n 56 \n(f)  To establish and operate procurement website,  \n(g)  To publish a bulletin in order to have made pu blic this Act and \nthe Regulations, Manuals, Technical Notes made ther eunder \nand public procurement related writings, article, m aterial and \nsimilar other matters,  \n(h)  To prepare procedures required for coordinatio n in the \nprocurement proceedings and submit to the Governmen t of \nNepal for approval,  \n(i)  To make arrangements for regular training prog ram for the \nbidder or the employee involved or to be involved i n \nprocurement proceedings,  \n(j)  To make necessary criteria of exclusion from t he blacklist \nunder Section 63 and exclude from such blacklist as  per such \ncriteria,  \n(k)  To review, appraise construction works, supply , consultancy \nservice, and other services system in order to make  the \nprocurement system effective, and to solicit regula rly \nsuggestion from customers or international organiza tion and \nother foreign bodies as per necessity,   \n(l)  To prepare plan of domestic or foreign assista nce required to \nsystematize and reform procurement system and to ac t as the \ncentral body for coordinating such assistance,  \n(m)  To submit the annual report of the procurement  proceedings to \nthe Government of Nepal, and  \n(n)  To do other prescribed functions.  \n(2) Notwithstanding anything contained in Sub-secti on (1), the Public \n 57 \nProcurement Monitoring Office shall not involve in any manner in the \nprocurement proceedings, except the procurement pro ceedings of its office, of \nother public entities nor shall resolve any dispute arisen in respect thereof.  \n(3) The Public Procurement Monitoring Office shall carry out the work \nof the secretariat of the Review Committee under Section 48 and it shall have to \nmake arrangements of the budget required for the committee.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": "Chapter-10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "66", "title": "Provision Concerning Procurement to be Made in  Special Circumstances :", "content": "(1) Notwithstanding anything contained elsewhere in  this Act, where the \noccurrence of special circumstance has created a si tuation in which, if a \nprocurement is not made immediately, the public ent ity will sustain further loss, \nthe Public Entity may procure or cause to be procured immediately.  \n(2) The chief of the Public Entity shall have to gi ve information of the \ncircumstances under Sub-section (1) and the detailed description concerning the \nprocurement to be made immediately to one level higher authority.  \n(3) Other provision concerning procurement to be ma de in special \ncircumstances shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Procurement Process under this Act not to be A pplied: (1) Notwithstanding", "content": "anything contained elsewhere in this Act, the procu rement process under this \nAct need not be applied in the following conditions:-  \n(a)  If the Government of Nepal decides that procur ement relating \nto security, strategic or defense by application of  the process \nin accordance with this Act is not appropriate for the interest \nof national security or defense , or  \n 58 \n(b)  If as per the agreement between government of Nepal and \ndonor party, procurement is to be made in accordanc e with the \nProcurement Guidelines of a donor party.  \n(2) In making a decision pursuant to clause (a) of Sub-section (1), \nGovernment of Nepal shall have to state reasons for procurement and determine \nseparate procedure related thereto as well.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Method of Communication : (1) Any document, notice, decision or other", "content": "information as referred to in this Act and Regulati ons made thereunder, bidding \ndocuments, documents relating to request for propos al or procurement contract \nas to be given by the Public Entity to a bidder, co nsultant or by a bidder or \nconsultant to the Public Entity shall, unless other wise provided for in this Act, \nbe given in writing.  \n(2) In case where a notice transmitted pursuant to Sub-section (1) could \nnot be served due to failure to trace out the addre ss of the recipient bidder or \nconsultant or for any other reason, a public notice  shall be published in a \nnewspaper of national circulation stating therein b rief description thereof and \nwhere a notice is so published such person shall be deemed to have received the \nnotice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Procurement Transaction May be Carried Out Thr ough Electronic", "content": "Communications Means : (1) Notwithstanding anything contained elsewhere \nin this Act, Government of Nepal may, by publicatio n of a notice in the Nepal \nGazette, provide a mechanism that the Public Entity  may arrange, through the \nmeans of electronic communications, invite a pre-qu alification proposal, issue \nnotice of bid invitation, prepare a short list by i nviting expression of interest, \ninvite a proposal of consultancy service, transmit bidding or pre-qualifying \ndocuments, receive bids, proposals for pre-qualific ation or consultancy \nservices, conclude the procurement contract, make p ayment and give and \nreceive other notices.   \n 59 \n(2) The means of communications under Sub-section ( 1) shall be used in \nthe following manner:-  \n(a) That the content of communications in such mean s of \ncommunications is legally valid and preserved,  \n(b)  That the security of such communications means  is adequate,  \n(c)  That bidder's access to the procurement procee ding is not \ninappropriately restricted,  \n(d)  That it is not in contravention of this Act an d rule made \nthereunder and other prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Legal Documents to be kept in Website : For information and convenience of", "content": "general public, this Act and Regulations and Procur ement Manuals made \nthereunder shall be kept in the website of the Publ ic Procurement Monitoring \nOffice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Evaluation Committee to be Formed : (1) The Public Entity shall have to", "content": "form an evaluation committee as prescribed for exam ination and evaluation of \nthe pre-qualification proposals, bids, expression o f interest or proposals of \nconsultancy services or sealed quotation.  \n(2) The functions, duties and powers of the committ ee formed pursuant \nto Sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "72", "title": "Records of Procurement Proceedings : The Public Entity shall have to keep", "content": "safely the records of the documents of the procurem ent proceedings for a \nprescribed period.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Delegation of Power : Out of the powers conferred on him/her by this Act or", "content": "rule made thereunder, a competent authority may del egate the powers other \nthan the prescribed one, to any staff.  \n  \n 60", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Power to Make Rules : (1) The Government of Nepal may make Rules", "content": "required for implementation of the objective of this Act.  \n(2) Notwithstanding any thing contained in Sub-sect ion (1), the Public \nEntity other than the one as referred to in sub-cla use (1) of clause (b) of \nSection 2 may make necessary Rules subject to the A ct, Rules or Formation \nOrder relating to such entity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Repeal and Amendment : (1) The provision to Section 168 of the Traffic and", "content": "Transportation Management Act, 1992 is hereby repe aled.  \n(2) Notwithstanding anything contained in prevailin g law, legal \nprovision relating to the procurement of the Public  Entity under clause (b) of \nSection 2 shall be deemed to have ipso facto  been so amended as to be \ncompatible to this Act to the extent of their inconsistency with this Act.  \n(3) Instead of Section 7 of Financial Procedure Act , 1998, the following \nSection 7 has been substituted:-  \n \"7 Procedure of Making Expenditure:  Provision concerning financial \nadministration relating to operation of government transactions and project \nimplementation, deposit, charges, service fee, taki ng advance and settlement \nthereof, preservation of government's cash and good s-in-and property, auction, \nremission, and other miscellaneous provision and pr ocedure related thereto \nshall be as prescribed.\"", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Saving : All the acts and proceedings relating to procuremen t carried out under", "content": "the Financial Procedure Act, 1998 and  the  Financial Administrations \nRegulations, 1999 made thereunder and the provision s of the Act, Rule or \nFormation Order related to procurement of the Publi c Entity as referred to in \nsub-clause (2), (3), (4), (5) and (6) of Clause (b) of Section 2 shall be deemed to \nhave been carried out under this Act.", "children": []}]}]$CODExe9430b96f806$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
